-- Synthetic SQL/RLS lifecycle. Real HTTP/Auth/Storage and simultaneous sessions
-- are separate checks. Every fixture and assertion is rolled back.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table editorial_test_values(key text primary key,value jsonb not null);
grant select,insert,update on editorial_test_values to authenticated;
create function pg_temp.command(input jsonb) returns jsonb language sql security invoker as $$
 select public.lawprep_editor_command(input||jsonb_build_object('mutationId',gen_random_uuid()));
$$;
insert into auth.users(id,email,email_confirmed_at,is_anonymous) values('14000000-0000-4000-8000-000000000001','publisher@example.invalid',now(),false);
insert into auth.sessions(id,user_id) values('15000000-0000-4000-8000-000000000001','14000000-0000-4000-8000-000000000001');
insert into lawprep_private.publisher_roles(user_id) values('14000000-0000-4000-8000-000000000001');
select set_config('request.jwt.claims','{"sub":"14000000-0000-4000-8000-000000000001","session_id":"15000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select pg_temp.command('{"op":"source","source":{"title":"Fixture","publisher":"Test","url":"javascript:alert(1)","checkedAt":"2026-10-28T00:00:00Z","rights":"unknown","reviewNote":""}}')$$,'22023',null,'direct RPC rejects unsafe URLs');
select throws_ok($$select pg_temp.command('{"op":"source","role":"publisher","source":{}}')$$,'22023',null,'direct RPC rejects privileged extra fields');
select throws_ok($$select pg_temp.command('{"op":"source","source":{"title":"\n","publisher":"Fixture","url":"https://example.org/source","checkedAt":"2026-10-28T00:00:00Z","rights":"unknown","reviewNote":""}}')$$,'22023',null,'whitespace-only source title cannot poison editor state');
select throws_ok($$select pg_temp.command('{"op":"source","source":{"title":"Fixture","publisher":"Fixture","url":"https://:","checkedAt":"2026-10-28T00:00:00Z","rights":"unknown","reviewNote":""}}')$$,'22023',null,'malformed HTTPS authority is rejected');
select throws_ok($$select pg_temp.command('{"op":"source","source":{"title":"Fixture","publisher":"Fixture","url":"https://example.org/source","checkedAt":"9999-12-31T23:59:59-14:00","rights":"unknown","reviewNote":""}}')$$,'22023',null,'normalized checked date cannot exceed ISO output year range');
select throws_ok($$select pg_temp.command('{"op":"source","source":{"title":"Fixture","publisher":"Fixture","url":"https://example.org/source","checkedAt":"0001-01-01T00:00:00+14:00","rights":"unknown","reviewNote":""}}')$$,'22023',null,'normalized checked date cannot become BC output');
insert into editorial_test_values values('source-command','{"op":"source","mutationId":"16000000-0000-4000-8000-000000000001","source":{"title":"Synthetic official reference","publisher":"Fixture","url":"https://example.org/fixture","checkedAt":"2026-10-28T00:00:00Z","rights":"permitted","reviewNote":"Synthetic rights checked"}}');
insert into editorial_test_values values('source',public.lawprep_editor_command((select value from editorial_test_values where key='source-command')));
select is(public.lawprep_editor_command((select value from editorial_test_values where key='source-command')),(select value from editorial_test_values where key='source'),'same input/mutation returns same result');
select throws_ok($$select public.lawprep_editor_command(jsonb_set((select value from editorial_test_values where key='source-command'),'{source,title}','"Changed input"'))$$,'23505',null,'changed input cannot reuse mutation identity');
insert into editorial_test_values values('unknown-source',pg_temp.command('{"op":"source","source":{"title":"Unknown rights","publisher":"Fixture","url":"https://example.org/unknown","checkedAt":"2026-10-28T00:00:00Z","rights":"unknown","reviewNote":""}}'));
select lives_ok($$select pg_temp.command(jsonb_build_object('op','cycle','cycle',jsonb_build_object('id','publication-fixture','examId','clat-ug','label','Synthetic cycle','sourceId',(select value->>'id' from editorial_test_values where key='source'),'sourceVerified',true)))$$,'reviewed source backs cycle');
select lives_ok($$select pg_temp.command('{"op":"topic","topic":{"id":"reading","cycleId":"publication-fixture","title":"Synthetic reading","prerequisiteIds":[]}}')$$,'cycle topic created');
insert into editorial_test_values values('draft-input',jsonb_build_object('cycleId','publication-fixture','topicId','reading','kind','question','title','Synthetic question','summary','Fixture summary','body','Private fixture body','visibility','public','sourceIds',jsonb_build_array((select value->>'id' from editorial_test_values where key='source')),'question','{"options":[{"id":" A ","text":" First "},{"id":"F","text":"Sixth identifier"}],"correctOptionId":" F ","explanation":"Private fixture explanation"}'::jsonb));
select throws_ok($$select pg_temp.command(jsonb_build_object('op','draft','draft',(select value from editorial_test_values where key='draft-input')||'{"verified":true}'))$$,'22023',null,'imported verification flags are not accepted');
select throws_ok($$select pg_temp.command(jsonb_build_object('op','draft','draft',jsonb_set((select value from editorial_test_values where key='draft-input'),'{question,correctOptionId}','"missing"')))$$,'22023',null,'key must match an option');
insert into editorial_test_values values('v1',pg_temp.command(jsonb_build_object('op','draft','draft',(select value from editorial_test_values where key='draft-input'))));
select is(jsonb_array_length(public.lawprep_catalog('clat-ug')->'items'),0,'unreviewed draft absent from public catalogue');
select throws_ok($$select pg_temp.command(jsonb_build_object('op','publish','versionId',(select value->>'id' from editorial_test_values where key='v1'),'note','Cannot publish unreviewed'))$$,'23514',null,'publication requires review');
select lives_ok($$select pg_temp.command(jsonb_build_object('op','review','versionId',(select value->>'id' from editorial_test_values where key='v1'),'sourceVerified',true,'rightsVerified',true,'answerVerified',true,'explanationVerified',true,'note','Checked synthetic sources, key, explanation and mapping'))$$,'review recorded');
select is(public.lawprep_editor_state((select (value->>'id')::uuid from editorial_test_values where key='v1'))->'selected'->'draft'->'question'->>'correctOptionId','F','editor preserves arbitrary valid answer identity');
select lives_ok($$select pg_temp.command(jsonb_build_object('op','publish','versionId',(select value->>'id' from editorial_test_values where key='v1'),'note','Publish reviewed synthetic fixture'))$$,'reviewed version publishes');
select is(jsonb_array_length(public.lawprep_catalog('clat-ug')->'items'),1,'published public summary appears');
select ok(position('Private fixture' in public.lawprep_catalog('clat-ug')::text)=0,'catalogue exposes neither body nor explanation');
insert into editorial_test_values values('v2',pg_temp.command(jsonb_build_object('op','draft','draft',(select value from editorial_test_values where key='draft-input')||jsonb_build_object('contentId',(public.lawprep_editor_state((select (value->>'id')::uuid from editorial_test_values where key='v1'))->'selected'->>'contentId'),'title','Corrected synthetic question'))));
select lives_ok($$select pg_temp.command(jsonb_build_object('op','review','versionId',(select value->>'id' from editorial_test_values where key='v2'),'sourceVerified',true,'rightsVerified',true,'answerVerified',true,'explanationVerified',true,'note','Reviewed corrected fixture'))$$,'replacement reviewed');
select lives_ok($$select pg_temp.command(jsonb_build_object('op','correct','versionId',(select value->>'id' from editorial_test_values where key='v1'),'replacementVersionId',(select value->>'id' from editorial_test_values where key='v2'),'note','Correct without rewriting history'))$$,'correction atomically swaps projection');
select is(public.lawprep_catalog('clat-ug')->'items'->0->>'title','Corrected synthetic question','public reader sees replacement');
select throws_ok($$select pg_temp.command(jsonb_build_object('op','withdraw','versionId',(select value->>'id' from editorial_test_values where key='v1'),'note','Stale withdrawal'))$$,'40001',null,'stale withdrawal cannot remove replacement');
select lives_ok($$select pg_temp.command(jsonb_build_object('op','withdraw','versionId',(select value->>'id' from editorial_test_values where key='v2'),'note','Withdraw future availability'))$$,'current version withdraws');
select is(jsonb_array_length(public.lawprep_catalog('clat-ug')->'items'),0,'withdrawn content unavailable to future catalogue readers');
insert into editorial_test_values values('bad-rights',pg_temp.command(jsonb_build_object('op','draft','draft',(select value from editorial_test_values where key='draft-input')||jsonb_build_object('sourceIds',jsonb_build_array((select value->>'id' from editorial_test_values where key='unknown-source'))))));
select lives_ok($$select pg_temp.command(jsonb_build_object('op','review','versionId',(select value->>'id' from editorial_test_values where key='bad-rights'),'sourceVerified',true,'rightsVerified',true,'answerVerified',true,'explanationVerified',true,'note','Attestation cannot override unknown source rights'))$$,'bad-rights review is still an immutable attestation');
select throws_ok($$select pg_temp.command(jsonb_build_object('op','publish','versionId',(select value->>'id' from editorial_test_values where key='bad-rights'),'note','Must remain blocked'))$$,'23514',null,'attestation cannot bypass unknown source rights');
reset role;
select is((select count(*)::integer from lawprep_private.content_versions where cycle_id='publication-fixture'),3,'original and corrected history preserved');
select is((select count(*)::integer from lawprep_private.version_keys k join lawprep_private.content_versions v on v.id=k.version_id where cycle_id='publication-fixture'),3,'historical keys preserved');
select is((select count(*)::integer from lawprep_private.publication_events where actor_id='14000000-0000-4000-8000-000000000001'),3,'publication, correction and withdrawal audit preserved');
select ok(not exists(select 1 from lawprep_private.version_keys k join lawprep_private.content_versions v on v.id=k.version_id where v.cycle_id='publication-fixture' and not exists(select 1 from jsonb_array_elements(v.structure->'options') option where option->>'id'=k.answer_key->>'correctOptionId')),'stored key exactly matches a canonical stored option');
select is((select count(*)::integer from lawprep_private.source_versions where publisher='Fixture' and title in ('Synthetic official reference','Unknown rights')),2,'duplicate source command did not duplicate synthetic source');
-- Same request UUID is deliberately publisher-scoped in receipts and audit.
insert into auth.users(id,email,email_confirmed_at,is_anonymous) values('14000000-0000-4000-8000-000000000002','publisher-b@example.invalid',now(),false);
insert into auth.sessions(id,user_id) values('15000000-0000-4000-8000-000000000002','14000000-0000-4000-8000-000000000002');
insert into lawprep_private.publisher_roles(user_id) values('14000000-0000-4000-8000-000000000002');
set local role authenticated;
insert into editorial_test_values values('shared-a',pg_temp.command(jsonb_build_object('op','draft','draft',(select value from editorial_test_values where key='draft-input'))));
select lives_ok($$select pg_temp.command(jsonb_build_object('op','review','versionId',(select value->>'id' from editorial_test_values where key='shared-a'),'sourceVerified',true,'rightsVerified',true,'answerVerified',true,'explanationVerified',true,'note','Shared-id publisher A review'))$$,'publisher A version reviewed');
select lives_ok($$select public.lawprep_editor_command(jsonb_build_object('op','publish','mutationId','17000000-0000-4000-8000-000000000001','versionId',(select value->>'id' from editorial_test_values where key='shared-a'),'note','Shared-id publisher A publish'))$$,'publisher A uses shared request UUID');
reset role;
select set_config('request.jwt.claims','{"sub":"14000000-0000-4000-8000-000000000002","session_id":"15000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
insert into editorial_test_values values('shared-b',pg_temp.command(jsonb_build_object('op','draft','draft',(select value from editorial_test_values where key='draft-input'))));
select lives_ok($$select pg_temp.command(jsonb_build_object('op','review','versionId',(select value->>'id' from editorial_test_values where key='shared-b'),'sourceVerified',true,'rightsVerified',true,'answerVerified',true,'explanationVerified',true,'note','Shared-id publisher B review'))$$,'publisher B version reviewed');
select lives_ok($$select public.lawprep_editor_command(jsonb_build_object('op','publish','mutationId','17000000-0000-4000-8000-000000000001','versionId',(select value->>'id' from editorial_test_values where key='shared-b'),'note','Shared-id publisher B publish'))$$,'publisher B can reuse same UUID within its own scope');
reset role;
select is((select count(*)::integer from lawprep_private.publication_events where mutation_id='17000000-0000-4000-8000-000000000001'),2,'both publisher-scoped audit events coexist');
delete from lawprep_private.publisher_roles where user_id='14000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claims','{"sub":"14000000-0000-4000-8000-000000000001","session_id":"15000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select public.lawprep_editor_command((select value from editorial_test_values where key='source-command'))$$,'42501',null,'role is rechecked before idempotent replay');
reset role;
select * from finish();
rollback;
